-- Programa oficial de fiestas 2026, transcrito del PDF facilitado.
-- Incluye la ampliación de coordenadas del mapa para que el panel pueda guardar ubicaciones.
-- Importación idempotente: no duplica actos con la misma fecha, hora y título.
alter table public.actos
  add column if not exists lat double precision,
  add column if not exists lng double precision;

insert into public.actos (dia, hora, titulo, descripcion, tipo, lugar, publicado)
